using Godot;
using System;
using System.Linq;
using System.Threading.Tasks;
public partial class MigrationScene {
 bool huntingCoopAck;
 [Rpc(MultiplayerApi.RpcMode.AnyPeer,TransferMode=MultiplayerPeer.TransferModeEnum.Reliable)]void CoopHuntingAck(){if(coopCheck&&CoopHost&&coopActors.ContainsKey(Multiplayer.GetRemoteSenderId()))huntingCoopAck=true;}
 async Task HuntingCoopChecks(CoopActor actor){var carcasses=game.World.Changes.Carcasses.ToList();var oldPieces=game.Building.Pieces.ToList();var oldPosition=actor.Body.Position;var oldStock=actor.Game.Craft.HuntStock.ToArray();bool oldKnife=actor.Game.Craft.SkinningKnife;int oldTool=actor.Game.Craft.HuntingTool;var oldHalves=actor.Game.Craft.HuntHalves.ToArray();int oldWood=actor.Game.Craft.Materials[0],oldFood=actor.Game.Life.Food;try{
  ClearEnemies();var at=Ground(HostPosition.X+12,HostPosition.Z+6);foreach(int dx in new[]{12,-12,18,-18}){var test=Ground(HostPosition.X+dx,HostPosition.Z+6);if(OutdoorFree(test.X,test.Z)){at=test;break;}}
  string id="fauna/deer/coop-hunting-check";AddEnemy(id,at.X,at.Z,1);var animal=infected.FirstOrDefault(e=>e.Id==id);MigrationChecks.Assert(animal!=null,"Co-op hunted animal fixture must spawn");KillEnemy(animal);actor.Body.Position=at+new Vector3(0,.2f,2);actor.Game.Craft.HuntStock=new int[6];actor.Game.Craft.HuntHalves=new int[6];actor.Game.Craft.SkinningKnife=true;actor.Game.Craft.HuntingTool=0;actor.Game.Craft.Materials[0]=4;actor.Game.Life.Food=2;
  int kind=Array.FindIndex(BuildDefinition.All,d=>d.Function=="cook"&&d.Tier==1);game.Building.Pieces.Add(new(){Id="coop-hunting-fire",Kind=kind,X=at.X+1,Y=at.Y,Z=at.Z+2,Health=100});SyncStructures();var hostStock=game.Craft.HuntStock.ToArray();int hostFood=game.Life.Food;huntingCoopAck=false;
  RpcId(actor.Id,nameof(CoopWorldUpdate),Json.Write(WorldSnapshot()));SendCoopPersonal(actor.Id,CoopProfileJson(actor.Game),"",actor.Body.Position,true);RpcId(actor.Id,nameof(CoopCheckStage),"hunting-harvest",at);await CoopWait(()=>huntingCoopAck,"Guest harvesting or cooking failed",20);
  MigrationChecks.Assert(actor.Game.Craft.HuntStock[0]==1&&actor.Game.Craft.HuntStock[1]==4&&actor.Game.Craft.HuntStock[3]==1&&actor.Game.Craft.HuntHalves[3]==1&&actor.Game.Craft.Materials[0]==3&&actor.Game.Life.Food==3,"Guest harvest/cook costs and yield were not conserved");MigrationChecks.Assert(game.Craft.HuntStock.SequenceEqual(hostStock)&&game.Life.Food==hostFood&&game.World.Changes.Carcasses.Single(c=>c.Id==id).Harvested,"Shared carcass must pay the guest once, not host");GD.Print("PASS / two-process hunting: real guest timed harvest, shared carcass, duplicate rejection, private meat/hide/bone and nearby-fire cooking costs");
 }finally{ClearEnemies();game.World.Changes.Carcasses=carcasses;game.Building.Pieces.Clear();game.Building.Pieces.AddRange(oldPieces);actor.Body.Position=oldPosition;actor.Game.Craft.HuntStock=oldStock;actor.Game.Craft.SkinningKnife=oldKnife;actor.Game.Craft.HuntingTool=oldTool;actor.Game.Craft.HuntHalves=oldHalves;actor.Game.Craft.Materials[0]=oldWood;actor.Game.Life.Food=oldFood;SyncStructures();RpcId(actor.Id,nameof(CoopWorldUpdate),Json.Write(WorldSnapshot()));}}
 async Task ClientHuntingChecks(){await CoopWait(()=>game.World.Changes.Carcasses.Any(c=>c.Id=="fauna/deer/coop-hunting-check"),"Carcass snapshot missing");CoopRequest("hunting","tool|2");await CoopWait(()=>game.Notice.Contains("Craft that"),"Unowned tool must be rejected");CoopRequest("hunting","tool|1");await CoopWait(()=>game.Craft.HuntingTool==1,"Skinning tool selection missing");string id="fauna/deer/coop-hunting-check";CoopRequest("hunting","harvest|"+id);await CoopWait(()=>game.Craft.HuntStock[0]==2,"Timed harvest materials missing",12);await CoopWait(()=>game.World.Changes.Carcasses.Single(c=>c.Id==id).Harvested,"Shared harvested flag missing");CoopRequest("hunting","harvest|"+id);await CoopWait(()=>game.Notice.Contains("Already harvested"),"Carcass duplicate was not rejected");CoopRequest("hunting","craft|0");await CoopWait(()=>game.Craft.HuntStock[0]==1&&game.Life.Food==3,"Campfire cooking result missing");RpcId(1,nameof(CoopHuntingAck));}
}
